import org.junit.Test;
import org.mockito.MockedStatic;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.mockito.Mockito.*;

public class CoreFunction_functionID_TriageGen0Test {

    private CoreFunction coreFunction;
    private EvalContext mockContext;
    private JXPathContext mockJXPathContext;
    private Expression mockArg1;
    private NodePointer mockNodePointer;

    @Before
    public void setUp() {
        // CoreFunction constructor requires functionCode and Expression array
        mockArg1 = mock(Expression.class);
        coreFunction = new CoreFunction(1, new Expression[]{mockArg1});

        mockContext = mock(EvalContext.class);
        mockJXPathContext = mock(JXPathContext.class);
        mockNodePointer = mock(NodePointer.class);

        when(mockContext.getJXPathContext()).thenReturn(mockJXPathContext);
        when(mockJXPathContext.getContextPointer()).thenReturn(mockNodePointer);
    }

    /**
     * Tests the successful execution of functionID.
     * Covers: line coverage and successful branch.
     */
    @Test
    public void testFunctionID_Success() {
        String targetId = "testId";
        Object expectedResult = new Object();

        // Mock the argument computation
        when(mockArg1.computeValue(mockContext)).thenReturn(targetId);
        // Mock the NodePointer behavior
        when(mockNodePointer.getPointerByID(mockJXPathContext, targetId)).thenReturn(expectedResult);

        // Use try-with-resources to mock static InfoSetUtil if necessary, 
        // but since we don't have the source of InfoSetUtil, we assume it's a standard utility.
        // If InfoSetUtil.stringValue is a static method, we mock it.
        try (MockedStatic<InfoSetUtil> infoSetUtilMock = mockStatic(InfoSetUtil.class)) {
            infoSetUtilMock.when(() -> InfoSetUtil.stringValue(targetId)).thenReturn(targetId);

            Object result = coreFunction.functionID(mockContext);

            assertNotNull(result);
            assertEquals(expectedResult, result);
            verify(mockArg1).computeValue(mockContext);
            verify(mockNodePointer).getPointerByID(mockJXPathContext, targetId);
        }
    }

    /**
     * Tests the scenario where assertArgCount(1) fails.
     * Since assertArgCount is protected and likely throws an exception if count != 1.
     * This tests the line coverage of the first line of the method.
     */
    @Test(expected = RuntimeException.class)
    public void testFunctionID_WrongArgumentCount() {
        // Create a function with 0 arguments to trigger assertion failure
        CoreFunction invalidFunction = new CoreFunction(2, new Expression[]{});
        invalidFunction.functionID(mockContext);
    }

    /**
     * Tests the scenario where the ID returned by InfoSetUtil is null or empty.
     */
    @Test
    public void testFunctionID_NullId() {
        String targetId = null;
        Object expectedResult = null;

        when(mockArg1.computeValue(mockContext)).thenReturn(null);
        when(mockNodePointer.getPointerByID(mockJXPathContext, targetId)).thenReturn(expectedResult);

        try (MockedStatic<InfoSetUtil> infoSetUtilMock = mockStatic(InfoSetUtil.class)) {
            infoSetUtilMock.when(() -> InfoSetUtil.stringValue(null)).thenReturn(null);

            Object result = coreFunction.functionID(mockContext);

            assertEquals(expectedResult, result);
        }
    }
}
